-- Import de 2331 articles et 4305 unites.
-- Quantite source -> tb_unite.qtunite; poids source -> tb_unite.poids.
-- codearticle = nouvel idca (3 chiffres) + nouvel idarticle (5 chiffres) + niveau (2 chiffres).
-- La table de correspondance est conservee jusqu'a 03_prix.sql.
BEGIN;
SET search_path TO public, pg_catalog;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM public.tb_article) OR EXISTS (SELECT 1 FROM public.tb_unite) OR EXISTS (SELECT 1 FROM public.tb_prix) THEN
        RAISE EXCEPTION 'La base cible doit etre vide pour les articles, unites et prix';
    END IF;
    IF to_regclass('public._ambanja_bazarbe_article_map') IS NOT NULL THEN
        RAISE EXCEPTION 'La table de correspondance existe deja; import deja commence';
    END IF;
END $$;

CREATE TABLE public._ambanja_bazarbe_article_map (
    source_group character varying(8) PRIMARY KEY,
    idarticle integer NOT NULL UNIQUE
);

WITH created_article AS (
    INSERT INTO public.tb_article
        (designation, idca, idmag, alert, alertdepot, deleted)
    SELECT 'BEST PM (sht plastique beste price pm)', c.idca, 1, 0, 0, 0
    FROM public.tb_categoriearticle c
    WHERE lower(btrim(c.designationcat)) = lower(btrim('Divers Non Alimentaire'))
      AND COALESCE(c.deleted, 0) = 0
    RETURNING idarticle
)
INSERT INTO public._ambanja_bazarbe_article_map (source_group, idarticle)
SELECT '00700001', idarticle FROM created_article;
