DO $$
BEGIN
    IF (SELECT COUNT(*) FROM public._ambanja_bazarbe_article_map) <> 2331 THEN
        RAISE EXCEPTION 'Nombre d articles importes incorrect';
    END IF;
    IF (SELECT COUNT(*) FROM public.tb_unite) <> 4305 THEN
        RAISE EXCEPTION 'Nombre d unites importees incorrect';
    END IF;
END $$;

SELECT setval(pg_get_serial_sequence('public.tb_article', 'idarticle'),
              GREATEST(COALESCE((SELECT MAX(idarticle) FROM public.tb_article), 1), 1), true);
SELECT setval(pg_get_serial_sequence('public.tb_unite', 'idunite'),
              GREATEST(COALESCE((SELECT MAX(idunite) FROM public.tb_unite), 1), 1), true);
COMMIT;
